return {["fb34_01"]={["down"]=[[fb34_03]],["dsc"]=[[你来到了天龙寺大门前，只见气势恢弘的两个大门柱上刻有一付对联红漆覆字，颇有点拨众生之意。抬头上望，门楣上一块黑木大匾，上题“崇圣寺”三个大字，笔意苍松。此乃正式寺名，但大理百性叫惯了，都称之为“天龙寺”。]],["id"]=[[fb34_01]],["item1"]=[[fb34item104]],["name"]=[[大门]],["permission"]=1,["role1"]=[[lbr01_1]],["role2"]=[[lbr01_2]],["role3"]=[[lbr01_3]],["stepMusic"]=[[jiaobu]]},["fb34_02"]={["dsc"]=[[这是天龙三塔之一，建于唐初，年代久远。传说月圆之夜，在此塔之下默许心愿，塔顶会出现圣光指点迷津，助你达成心愿。]],["id"]=[[fb34_02]],["name"]=[[舍利塔]],["permission"]=2,["right"]=[[fb34_03]],["role1"]=[[fb34r02_1]],["role2"]=[[fb34r02_2]],["stepMusic"]=[[jiaobu]]},["fb34_03"]={["down"]=[[fb34_06]],["dsc"]=[[这是一片塔林。放眼望去，林林总总有不下百座高矮不一的石塔，这些都是达官显贵们捐资修筑的，或是为了祈求菩萨保佑，或是为了还愿平心。东西北三面各有一座高塔。]],["id"]=[[fb34_03]],["item1"]=[[fb34item1]],["left"]=[[fb34_02]],["name"]=[[塔林]],["permission"]=1,["right"]=[[fb34_04]],["role1"]=[[fb34r03_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb34_01]]},["fb34_04"]={["dsc"]=[[这是天龙三塔之一，建于唐初，年代久远。虽然塔身已经石迹斑驳，但是仍然耸立挺拔，俨然是天龙寺百年威名的象征。]],["id"]=[[fb34_04]],["left"]=[[fb34_03]],["name"]=[[舍利塔]],["permission"]=2,["role1"]=[[fb34r04_1]],["role2"]=[[fb34r04_2]],["stepMusic"]=[[jiaobu]]},["fb34_05"]={["down"]=[[fb34_08]],["dsc"]=[[这是历代大理王侯前来进香还愿时休息的地方。阁内檀象宝炉，软榻矮几，一应俱全，清静之中隐然透出一丝富贵之象。]],["id"]=[[fb34_05]],["item1"]=[[fb34item7]],["item2"]=[[fb34item8]],["name"]=[[无净阁]],["permission"]=2,["right"]=[[fb34_06]],["role1"]=[[fb34r05_3]],["role2"]=[[fb34r05_4]],["stepMusic"]=[[jiaobu]]},["fb34_06"]={["down"]=[[fb34_09]],["dsc"]=[[这是天龙三塔中最高的一座，高约三百余尺，共有十六级。相传塔顶原本供奉着一颗前代高僧的舍利子，但在当年奸臣杨义贞弑上德帝篡位以至天下大乱时，舍利子不知何因而失踪了，这也成为天龙寺历代主持的心腹大事。这个传言也不知是真是假。]],["id"]=[[fb34_06]],["left"]=[[fb34_05]],["name"]=[[舍利塔]],["permission"]=1,["right"]=[[fb34_07]],["role1"]=[[fb34r06_1]],["role2"]=[[fb34r06_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb34_03]]},["fb34_07"]={["down"]=[[fb34_10]],["dsc"]=[[这是历代大理王侯前来进香还愿时休息的地方。阁内檀象宝炉，软榻矮几，一应俱全，清静之中隐然透出一丝富贵之象。]],["id"]=[[fb34_07]],["item1"]=[[fb34item7]],["left"]=[[fb34_06]],["name"]=[[无我阁]],["permission"]=1,["stepMusic"]=[[jiaobu]]},["fb34_08"]={["down"]=[[fb34_11]],["dsc"]=[[这是通往天龙寺后寺的门户。你低头看看地上，只见铜门槛早已被踩踏得锃亮，足见此寺香火之盛了。抬头向南可以望见点苍山耸立云天。]],["id"]=[[fb34_08]],["name"]=[[翔鹤门]],["permission"]=2,["role1"]=[[fb34r08_1]],["role2"]=[[2019qxcdg1a]],["role3"]=[[2019qxcdg1b]],["stepMusic"]=[[jiaobu]],["up"]=[[fb34_05]]},["fb34_09"]={["dsc"]=[[这是一座宽广的大殿，正面有一座高约二十余尺的佛祖宝像，通体金光耀眼。座下香烟缭绕。大殿两旁树立两根檀木大柱，题有一联，云曰:守口摄意身莫犯，莫恼一切诸有情。]],["id"]=[[fb34_09]],["item1"]=[[fb34item15]],["name"]=[[崇圣宝殿]],["permission"]=2,["role1"]=[[fb34r09_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb34_06]]},["fb34_10"]={["down"]=[[fb34_13]],["dsc"]=[[这是通往天龙寺后寺的门户。你低头看看地上，只见铜门槛早已被踩踏得锃亮，足见此寺香火之盛了。抬头向南可以望见点苍山耸立云天。]],["id"]=[[fb34_10]],["name"]=[[瑞鹤门]],["permission"]=1,["rightDown"]=[[fb34_43]],["role1"]=[[fb34r10_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb34_07]]},["fb34_11"]={["dsc"]=[[这是历代大理王侯前来进香还愿时休息的地方。阁内檀象宝炉，软榻矮几，一应俱全，清静之中隐然透出一丝富贵之象。]],["id"]=[[fb34_11]],["item1"]=[[fb34item7]],["item2"]=[[fb34item101]],["name"]=[[无乐阁]],["permission"]=2,["right"]=[[fb34_12]],["stepMusic"]=[[jiaobu]],["up"]=[[fb34_08]]},["fb34_12"]={["down"]=[[fb34_14]],["dsc"]=[[这是出入前后寺的必经之路。往南望去，可见后寺中亭台楼阁规模宏大，构筑精丽，宅地连云，其气势之盛更胜于五台，普陀等诸处佛门胜地的名山大寺。]],["id"]=[[fb34_12]],["left"]=[[fb34_11]],["name"]=[[晃天阁]],["permission"]=1,["right"]=[[fb34_13]],["role1"]=[[fb34r12_1]],["role2"]=[[fb34r12_2]],["stepMusic"]=[[jiaobu]]},["fb34_13"]={["dsc"]=[[这是历代大理王侯前来进香还愿时休息的地方。阁内檀象宝炉，软榻矮几，一应俱全，清静之中隐然透出一丝富贵之象。]],["id"]=[[fb34_13]],["item1"]=[[fb34item7]],["left"]=[[fb34_12]],["name"]=[[无常阁]],["permission"]=1,["stepMusic"]=[[jiaobu]],["up"]=[[fb34_10]]},["fb34_14"]={["down"]=[[fb34_16]],["dsc"]=[[这是出入前后寺的必经之路。往南望去，可见后寺中亭台楼阁规模宏大，构筑精丽，宅地连云，其气势之盛更胜于五台，普陀等诸处佛门胜地的名山大寺。]],["id"]=[[fb34_14]],["name"]=[[清都瑶池]],["permission"]=1,["role1"]=[[fb34r14_100]],["role2"]=[[fb34r14_101]],["stepMusic"]=[[jiaobu]],["up"]=[[fb34_12]]},["fb34_15"]={["down"]=[[fb34_18]],["dsc"]=[[这是僧人们点化顽徒的地方。不少江湖豪客由于厌倦了打打杀杀的日子，来到此处落发为僧，皈依佛门。墙上一幅佛祖神像，两边各有一条幅，上书:放下屠刀，立地成佛。]],["id"]=[[fb34_15]],["name"]=[[慈悲院]],["permission"]=2,["right"]=[[fb34_16]],["role1"]=[[fb34r15_1]],["role2"]=[[fb34r15_2]],["role3"]=[[fb34r15_3]],["stepMusic"]=[[jiaobu]]},["fb34_16"]={["down"]=[[fb34_19]],["dsc"]=[[忽然眼前景物一变，一座半人高矮围墙里竹林似海，幽静无比，小路从中轻轻穿过，通向院外的雨花院。这里种植的全是西南名竹--云竹。每当轻风吹过，吹得竹干摇摆，如云如海，在你身边一浪浪抚过，使你心中似有所动。东边一条石板路延伸向远方。]],["id"]=[[fb34_16]],["item1"]=[[fb34item2]],["item2"]=[[fb34item105]],["left"]=[[fb34_15]],["name"]=[[无无镜]],["permission"]=1,["right"]=[[fb34_17]],["stepMusic"]=[[jiaobu]],["up"]=[[fb34_14]]},["fb34_17"]={["down"]=[[fb34_20]],["dsc"]=[[相传当年佛祖降临天龙寺传法时，漫天遍洒雨花石。后人以石建院，即成此间玉花院。院中常年檀香四溢，令人心旷神怡。]],["id"]=[[fb34_17]],["left"]=[[fb34_16]],["name"]=[[雨花院]],["permission"]=2,["role1"]=[[fb34r17_1]],["role2"]=[[fb34r17_2]],["role3"]=[[fb34r17_3]],["stepMusic"]=[[jiaobu]]},["fb34_18"]={["dsc"]=[[这里可以买香到后面参拜西方大士。几个进香客正围着一个老年僧人讨价还价。]],["id"]=[[fb34_18]],["name"]=[[三无宫]],["permission"]=2,["rightDown"]=[[fb34_22]],["role1"]=[[fb34r18_1]],["role2"]=[[fb34r18_2]],["role3"]=[[fb34r18_3]],["stepMusic"]=[[jiaobu]],["up"]=[[fb34_15]]},["fb34_19"]={["down"]=[[fb34_22]],["dsc"]=[[这是寺中诸僧前去后院参修之前清心净欲的地方。阁中只有地面放有几个蒲团，除此之外别无它物，确然是个清静之处。]],["id"]=[[fb34_19]],["item1"]=[[fb34item107]],["name"]=[[清心阁]],["permission"]=1,["role1"]=[[fb34r19_100]],["role2"]=[[fb34r19_101]],["stepMusic"]=[[jiaobu]],["up"]=[[fb34_16]]},["fb34_20"]={["dsc"]=[[这是给进香客们休息的地方。四周围放着一溜檀木红漆椅。几个进香客坐在上面休息。]],["id"]=[[fb34_20]],["leftDown"]=[[fb34_22]],["name"]=[[斗母宫]],["permission"]=2,["role1"]=[[fb34r20_1]],["role2"]=[[fb34r20_2]],["role3"]=[[fb34r20_3]],["stepMusic"]=[[jiaobu]],["up"]=[[fb34_17]]},["fb34_21"]={["dsc"]=[[你进入了一间小松木屋，木屋门上挂了一个牌匾，上边写着“龙树院”，你吃了一惊，想不到大名鼎鼎的天龙寺龙树院竟然就是这间小屋。四周的窗户都打开着，从窗外透射进一丝阳光将木屋内照亮。]],["id"]=[[fb34_21]],["item1"]=[[fb34item14]],["name"]=[[龙树院]],["permission"]=1,["role1"]=[[fb34r21_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb34_35]]},["fb34_22"]={["down"]=[[fb34_24]],["dsc"]=[[这是一般参拜者所能到的最远的地方，再往南就是天龙寺历代高僧静修之处――牟尼堂。那是常人不可轻易打搅的地方，你最好不要擅自闯入。除非你确信能给高僧们带去好消息。]],["id"]=[[fb34_22]],["item1"]=[[fb34item3]],["item2"]=[[bfitem1]],["leftUp"]=[[fb34_18]],["name"]=[[兜率大士院]],["permission"]=1,["rightUp"]=[[fb34_20]],["stepMusic"]=[[jiaobu]],["up"]=[[fb34_19]]},["fb34_23"]={["dsc"]=[[此处依山傍水，一条小溪从你眼前静静流过，一座精雕木桥横跨其上，与其倒影恰成一圆，映着空灵的水面。溪旁遍植百花，风吹花落，便有了雨花院之称。院内雨花阁精舍乃是寺中藏经存书之处，虽有几个和尚来来去去，却不闻一丝声响。]],["id"]=[[fb34_23]],["name"]=[[雨花院]],["permission"]=2,["right"]=[[fb34_30]],["role1"]=[[fb34r23_1]],["role2"]=[[fb34r23_2]],["role3"]=[[fb34r23_3]],["stepMusic"]=[[jiaobu]]},["fb34_24"]={["down"]=[[fb34_27]],["dsc"]=[[这是个普通的石台，相传当年佛祖曾降临此台传法。再往南去就是本寺重地――牟尼堂。江湖中传言天龙寺的镇寺之宝――气脉奇剑谱就藏于此中，但你千万不要打什么主意。]],["id"]=[[fb34_24]],["item1"]=[[fb34item4]],["name"]=[[般若台]],["permission"]=1,["stepMusic"]=[[jiaobu]],["up"]=[[fb34_22]]},["fb34_25"]={["dsc"]=[[一片水池静卧眼前，一座精雕木桥横跨其上，与其倒影恰成一圆，映着空灵的水面，使你心中似有所动。仿佛体会到了众生之源，万物之本的真谛。]],["id"]=[[fb34_25]],["name"]=[[无无境]],["permission"]=2,["right"]=[[fb34_26]],["role1"]=[[fb34r25_2]],["stepMusic"]=[[jiaobu]]},["fb34_26"]={["down"]=[[fb34_28]],["dsc"]=[[你走在一条长长的石板路上，道旁古树参天，鸟鸣不绝，前面是一片大松林，这条路一直通向松林深处，林子里黑黑漆漆的，你不由的默念“阿弥陀佛”。]],["id"]=[[fb34_26]],["left"]=[[fb34_25]],["name"]=[[长廊]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb34_30]]},["fb34_27"]={["down"]=[[fb34_29]],["dsc"]=[[这是高僧们的静修之处。整堂全以松木制成，板门木柱，木料均不去皮，天然质朴，和一路行来金碧辉煌的殿堂截然不同。东首一个和尚面朝里壁一动不动。]],["id"]=[[fb34_27]],["name"]=[[牟尼堂]],["permission"]=1,["role1"]=[[fb34r27_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb34_24]]},["fb34_28"]={["dsc"]=[[这里又是一段白石路，石面平滑，打扫得干干净净。路旁种有各式花草，两株参天大树分立左右两边。]],["id"]=[[fb34_28]],["leftDown"]=[[fb34_29]],["name"]=[[小路]],["permission"]=2,["role1"]=[[fb34r28_1]],["role2"]=[[fb34r28_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb34_26]]},["fb34_29"]={["dsc"]=[[由此过去一路都是碎石路了，这一带只准寺内僧侣进入，其它人等如果没有方丈许可是不可以来此的。]],["id"]=[[fb34_29]],["item1"]=[[fb34item100]],["name"]=[[瑶台]],["permission"]=2,["rightUp"]=[[fb34_28]],["role1"]=[[fb34r29_100]],["stepMusic"]=[[jiaobu]],["up"]=[[fb34_27]]},["fb34_30"]={["down"]=[[fb34_26]],["dsc"]=[[这里是一片茂密的松树林，松树高大，枝叶茂盛，你一走进来差点便迷失了方向。这里灌木丛生，路都给挡住了。]],["fightBackground"]=[[森林内]],["id"]=[[fb34_30]],["item1"]=[[fb34item13]],["left"]=[[fb34_23]],["leftUp"]=[[fb34_36]],["name"]=[[松林]],["permission"]=2,["right"]=[[fb34_41]],["stepMusic"]=[[jiaobu]],["up"]=[[fb34_31]]},["fb34_31"]={["down"]=[[fb34_30]],["dsc"]=[[这里是一片茂密的松树林，松树高大，枝叶茂盛，你一走进来差点便迷失了方向。这里灌木丛生，路都给挡住了。]],["fightBackground"]=[[森林内]],["id"]=[[fb34_31]],["left"]=[[fb34_36]],["leftUp"]=[[fb34_42]],["name"]=[[松林]],["permission"]=2,["right"]=[[fb34_41]],["rightUp"]=[[fb34_32]],["stepMusic"]=[[jiaobu]],["up"]=[[fb34_41]]},["fb34_32"]={["down"]=[[fb34_41]],["dsc"]=[[这里是一片茂密的松树林，松树高大，枝叶茂盛，你一走进来差点便迷失了方向。这里灌木丛生，路都给挡住了。]],["fightBackground"]=[[森林内]],["id"]=[[fb34_32]],["left"]=[[fb34_41]],["leftDown"]=[[fb34_31]],["name"]=[[松林]],["permission"]=2,["right"]=[[fb34_33]],["rightUp"]=[[fb34_38]],["stepMusic"]=[[jiaobu]],["up"]=[[fb34_37]]},["fb34_33"]={["down"]=[[fb34_34]],["dsc"]=[[这里是一片茂密的松树林，松树高大，枝叶茂盛，你一走进来差点便迷失了方向。这里灌木丛生，路都给挡住了。]],["fightBackground"]=[[森林内]],["id"]=[[fb34_33]],["left"]=[[fb34_32]],["leftUp"]=[[fb34_37]],["name"]=[[松林]],["permission"]=2,["right"]=[[fb34_41]],["rightDown"]=[[fb34_39]],["stepMusic"]=[[jiaobu]],["up"]=[[fb34_38]]},["fb34_34"]={["down"]=[[fb34_41]],["dsc"]=[[这里是一片茂密的松树林，松树高大，枝叶茂盛，你一走进来差点便迷失了方向。这里灌木丛生，路都给挡住了。]],["fightBackground"]=[[森林内]],["id"]=[[fb34_34]],["left"]=[[fb34_41]],["leftDown"]=[[fb34_35]],["name"]=[[松林]],["permission"]=2,["right"]=[[fb34_39]],["rightDown"]=[[fb34_40]],["stepMusic"]=[[jiaobu]],["up"]=[[fb34_33]]},["fb34_35"]={["down"]=[[fb34_41]],["dsc"]=[[这里是一片茂密的松树林，松树高大，枝叶茂盛，你一走进来差点便迷失了方向。这里灌木丛生，路都给挡住了。]],["fightBackground"]=[[森林内]],["id"]=[[fb34_35]],["left"]=[[fb34_41]],["name"]=[[松林]],["permission"]=2,["right"]=[[fb34_41]],["rightUp"]=[[fb34_34]],["stepMusic"]=[[jiaobu]],["up"]=[[fb34_21]]},["fb34_36"]={["down"]=[[fb34_41]],["dsc"]=[[这里是一片茂密的松树林，松树高大，枝叶茂盛，你一走进来差点便迷失了方向。这里灌木丛生，路都给挡住了。]],["fightBackground"]=[[森林内]],["id"]=[[fb34_36]],["left"]=[[fb34_41]],["name"]=[[松林]],["permission"]=2,["right"]=[[fb34_31]],["rightDown"]=[[fb34_30]],["stepMusic"]=[[jiaobu]],["up"]=[[fb34_42]]},["fb34_37"]={["down"]=[[fb34_32]],["dsc"]=[[这里是一片茂密的松树林，松树高大，枝